CREATE SEQUENCE IF NOT EXISTS subscription_seq START 1;
CREATE SEQUENCE IF NOT EXISTS invoice_seq START 1;
CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY,email TEXT NOT NULL,password_hash TEXT NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('admin','staff','customer')),is_active BOOLEAN NOT NULL DEFAULT TRUE,created_by BIGINT REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS users_email_uq ON users(lower(email));
CREATE TABLE IF NOT EXISTS password_resets (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash TEXT NOT NULL,expires_at TIMESTAMPTZ NOT NULL,used_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS password_resets_token_idx ON password_resets(token_hash);
CREATE TABLE IF NOT EXISTS customers (id BIGSERIAL PRIMARY KEY,user_id BIGINT UNIQUE REFERENCES users(id) ON DELETE SET NULL,name TEXT NOT NULL,email TEXT NOT NULL,phone TEXT,company TEXT,billing_address TEXT,legacy_id TEXT,migration_job_id BIGINT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS customers_email_uq ON customers(lower(email));
CREATE TABLE IF NOT EXISTS products (id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,type TEXT NOT NULL,sales_price NUMERIC(12,2) NOT NULL DEFAULT 0,cost_price NUMERIC(12,2) NOT NULL DEFAULT 0,notes TEXT,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS product_variants (id BIGSERIAL PRIMARY KEY,product_id BIGINT NOT NULL REFERENCES products(id) ON DELETE CASCADE,attribute TEXT NOT NULL,value TEXT NOT NULL,extra_price NUMERIC(12,2) NOT NULL DEFAULT 0,UNIQUE(product_id,attribute,value));
CREATE TABLE IF NOT EXISTS plans (id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,price NUMERIC(12,2) NOT NULL DEFAULT 0,billing_period TEXT NOT NULL CHECK(billing_period IN('daily','weekly','monthly','yearly')),min_quantity INT NOT NULL DEFAULT 1,valid_from DATE,valid_to DATE,auto_close BOOLEAN NOT NULL DEFAULT FALSE,closable BOOLEAN NOT NULL DEFAULT TRUE,pausable BOOLEAN NOT NULL DEFAULT FALSE,renewable BOOLEAN NOT NULL DEFAULT TRUE,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tax_rules (id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,rate NUMERIC(5,2) NOT NULL,applies_to TEXT NOT NULL CHECK(applies_to IN('all','product_type','product')),product_type TEXT,product_id BIGINT REFERENCES products(id) ON DELETE CASCADE,is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS discounts (id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,type TEXT NOT NULL CHECK(type IN('fixed','percent')),value NUMERIC(12,2) NOT NULL,min_purchase NUMERIC(12,2) NOT NULL DEFAULT 0,min_quantity INT NOT NULL DEFAULT 0,start_date DATE,end_date DATE,usage_limit INT,used_count INT NOT NULL DEFAULT 0,applies_to TEXT NOT NULL CHECK(applies_to IN('product','subscription')),product_id BIGINT REFERENCES products(id) ON DELETE CASCADE,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_by BIGINT REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payment_terms (id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL UNIQUE,days INT NOT NULL CHECK(days >= 0));
CREATE TABLE IF NOT EXISTS quote_templates (id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,plan_id BIGINT NOT NULL REFERENCES plans(id),validity_days INT NOT NULL DEFAULT 15,payment_term_id BIGINT REFERENCES payment_terms(id),term_months INT NOT NULL DEFAULT 12,notes TEXT,is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS quote_template_lines (id BIGSERIAL PRIMARY KEY,template_id BIGINT NOT NULL REFERENCES quote_templates(id) ON DELETE CASCADE,product_id BIGINT NOT NULL REFERENCES products(id),variant_id BIGINT REFERENCES product_variants(id),quantity INT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS subscriptions (id BIGSERIAL PRIMARY KEY,number TEXT NOT NULL UNIQUE,customer_id BIGINT NOT NULL REFERENCES customers(id),plan_id BIGINT NOT NULL REFERENCES plans(id),status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','quotation','confirmed','active','closed')),start_date DATE NOT NULL,expiry_date DATE NOT NULL,payment_term_id BIGINT REFERENCES payment_terms(id),template_id BIGINT REFERENCES quote_templates(id),quote_sent_on DATE,quote_valid_until DATE,next_billing_date DATE,billing_anchor_day INT,paused_at DATE,close_reason TEXT,notes TEXT,is_historical BOOLEAN NOT NULL DEFAULT FALSE,legacy_id TEXT,migration_job_id BIGINT,created_by BIGINT REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),activated_at TIMESTAMPTZ,closed_at TIMESTAMPTZ,CHECK(expiry_date >= start_date));
CREATE TABLE IF NOT EXISTS subscription_lines (id BIGSERIAL PRIMARY KEY,subscription_id BIGINT NOT NULL REFERENCES subscriptions(id) ON DELETE CASCADE,product_id BIGINT NOT NULL REFERENCES products(id),variant_id BIGINT REFERENCES product_variants(id),quantity INT NOT NULL CHECK(quantity > 0),unit_price NUMERIC(12,2) NOT NULL,tax_rate NUMERIC(5,2) NOT NULL DEFAULT 0,amount NUMERIC(12,2) NOT NULL);
CREATE TABLE IF NOT EXISTS billing_runs (id BIGSERIAL PRIMARY KEY,as_of_date DATE NOT NULL,dry_run BOOLEAN NOT NULL,status TEXT NOT NULL DEFAULT 'running',scanned INT NOT NULL DEFAULT 0,invoices_created INT NOT NULL DEFAULT 0,total_amount NUMERIC(14,2) NOT NULL DEFAULT 0,errors JSONB NOT NULL DEFAULT '[]',started_by BIGINT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),finished_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS invoices (id BIGSERIAL PRIMARY KEY,number TEXT NOT NULL UNIQUE,subscription_id BIGINT NOT NULL REFERENCES subscriptions(id),customer_id BIGINT NOT NULL REFERENCES customers(id),status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','confirmed','paid','cancelled')),invoice_date DATE NOT NULL,due_date DATE NOT NULL,period_start DATE NOT NULL,period_end DATE NOT NULL,subtotal NUMERIC(12,2) NOT NULL,discount_total NUMERIC(12,2) NOT NULL DEFAULT 0,tax_total NUMERIC(12,2) NOT NULL DEFAULT 0,total NUMERIC(12,2) NOT NULL,amount_paid NUMERIC(12,2) NOT NULL DEFAULT 0,currency TEXT NOT NULL DEFAULT 'INR',payment_term_name TEXT,calc_trail JSONB,billing_run_id BIGINT REFERENCES billing_runs(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(subscription_id,period_start));
CREATE TABLE IF NOT EXISTS invoice_lines (id BIGSERIAL PRIMARY KEY,invoice_id BIGINT NOT NULL REFERENCES invoices(id) ON DELETE CASCADE,kind TEXT NOT NULL DEFAULT 'product',product_id BIGINT,variant_id BIGINT,description TEXT NOT NULL,quantity INT NOT NULL,unit_price NUMERIC(12,2) NOT NULL,line_subtotal NUMERIC(12,2) NOT NULL,discount_amount NUMERIC(12,2) NOT NULL DEFAULT 0,discount_id BIGINT,sub_discount_amount NUMERIC(12,2) NOT NULL DEFAULT 0,sub_discount_id BIGINT,tax_rule_id BIGINT,tax_rate NUMERIC(5,2) NOT NULL DEFAULT 0,tax_amount NUMERIC(12,2) NOT NULL DEFAULT 0,line_total NUMERIC(12,2) NOT NULL,calc_trail JSONB);
CREATE TABLE IF NOT EXISTS payments (id BIGSERIAL PRIMARY KEY,invoice_id BIGINT NOT NULL REFERENCES invoices(id),method TEXT NOT NULL,amount NUMERIC(12,2) NOT NULL,paid_on DATE NOT NULL,note TEXT,reference TEXT,recorded_by BIGINT REFERENCES users(id),voided_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS events (id BIGSERIAL PRIMARY KEY,entity_type TEXT NOT NULL,entity_id BIGINT,subscription_id BIGINT,customer_id BIGINT,event_type TEXT NOT NULL,message TEXT NOT NULL,meta JSONB,actor_id BIGINT,occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(),sim_date DATE);
CREATE TABLE IF NOT EXISTS app_settings (key TEXT PRIMARY KEY,value JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS email_log (id BIGSERIAL PRIMARY KEY,to_email TEXT NOT NULL,subject TEXT NOT NULL,body TEXT NOT NULL,kind TEXT,delivered BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS subs_active_billing_idx ON subscriptions(next_billing_date) WHERE status='active' AND paused_at IS NULL;
CREATE INDEX IF NOT EXISTS invoices_status_due_idx ON invoices(status,due_date);
